pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, uint256 value, bytes memory data, uint256 extraDeposits) public {
        // Restrict value to avoid overflow in the reference (max 255 deposits with value > 0)
        // and bound extraDeposits to stay within reasonable limits
        value = bound(value, 0, 1 ether);
        extraDeposits = bound(extraDeposits, 0, 100);

        // Record initial deposits count
        uint256 initialCount = c.depositsCount();

        // Perform some direct deposits (sending ether to receive())
        for (uint i = 0; i < extraDeposits; i++) {
            (bool success,) = address(c).call{value: 1 wei}("");
            require(success, "deposit failed");
        }

        uint256 beforeSend = c.depositsCount();

        // Call sendMoney
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, target, value, data));

        uint256 afterSend = c.depositsCount();

        // Rule: depositsCount should never exceed the expected maximum
        // Maximum possible increments: initialCount + extraDeposits + (value > 0 ? 1 : 0)
        // Actually, sendMoney does NOT increment depositsCount (it calls call, not receive)
        // So depositsCount should not increase due to sendMoney
        uint256 expectedMax = initialCount + extraDeposits;
        assertTrue(afterSend <= expectedMax, "depositsCount increased unexpectedly");
    }
}

