import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 value, bytes calldata data) public {
        vm.assume(sender != address(c));
        vm.assume(sender != address(0));
        // Ensure the contract has some balance for the test
        vm.deal(address(c), 1 ether);
        // But the sendMoney call will try to send more than the contract has
        uint256 excessiveValue = bound(value, address(c).balance + 1, type(uint256).max);

        uint256 senderBalanceBefore = sender.balance;

        vm.prank(sender);
        // try/catch because reference contract will revert on failing transfer, mutant will not
        try c.sendMoney(sender, excessiveValue, data) {
            // If call succeeds, check the rule: sender's balance should not increase
            uint256 senderBalanceAfter = sender.balance;
            assertTrue(senderBalanceAfter == senderBalanceBefore, "Owner balance should not change");
        } catch {
            // If it reverts, the reference contract behaved correctly, rule holds
            assertTrue(true);
        }
    }
}

